=== FILE: sync_fifo.v ===
`timescale 1ns / 1ps
`default_nettype none

// sync_fifo: single-clock first-in, first-out buffer.
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
// - Storage `mem` is datapath: not reset, written only outside reset.
// - Pointers wrap by comparing against LAST (DEPTH-1), so any DEPTH >= 2 works.
// - Occupancy is an explicit `count` register; full/empty are compares on it.
// - First-word fall-through: rd_data = mem[rd_ptr], combinational.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    // Widths
    localparam integer AW = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer CW = $clog2(DEPTH + 1);

    // 32-bit constants, then exact-width constants taken by part-select
    localparam [31:0] ONE32    = 32'd1;
    localparam [31:0] DEPTH_U  = DEPTH;
    localparam [31:0] DEPTH_M1 = DEPTH - 1;

    localparam [AW-1:0] LAST       = DEPTH_M1[AW-1:0];
    localparam [AW-1:0] PTR_ONE    = ONE32[AW-1:0];
    localparam [AW-1:0] PTR_ZERO   = {AW{1'b0}};
    localparam [CW-1:0] CNT_ONE    = ONE32[CW-1:0];
    localparam [CW-1:0] CNT_ZERO   = {CW{1'b0}};
    localparam [CW-1:0] FULL_COUNT = DEPTH_U[CW-1:0];

    // Storage (datapath, no reset)
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // State
    reg [AW-1:0] wr_ptr_q;
    reg [AW-1:0] rd_ptr_q;
    reg [CW-1:0] count_q;

    // Next state
    reg [AW-1:0] wr_ptr_d;
    reg [AW-1:0] rd_ptr_d;
    reg [CW-1:0] count_d;

    // Flags and acceptance
    wire wr_acc;
    wire rd_acc;

    assign full    = (count_q == FULL_COUNT);
    assign empty   = (count_q == CNT_ZERO);
    assign count   = count_q;
    assign wr_acc  = wr_en & ~full;
    assign rd_acc  = rd_en & ~empty;
    assign rd_data = mem[rd_ptr_q];

    // Write pointer: advance on an accepted write, wrap after LAST
    always @* begin
        wr_ptr_d = wr_ptr_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST) begin
                wr_ptr_d = PTR_ZERO;
            end else begin
                wr_ptr_d = wr_ptr_q + PTR_ONE;
            end
        end
    end

    // Read pointer: advance on an accepted read, wrap after LAST
    always @* begin
        rd_ptr_d = rd_ptr_q;
        if (rd_acc) begin
            if (rd_ptr_q == LAST) begin
                rd_ptr_d = PTR_ZERO;
            end else begin
                rd_ptr_d = rd_ptr_q + PTR_ONE;
            end
        end
    end

    // Occupancy: +1 on write only, -1 on read only, hold otherwise
    always @* begin
        count_d = count_q;
        if (wr_acc && !rd_acc) begin
            count_d = count_q + CNT_ONE;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - CNT_ONE;
        end
    end

    // Control registers: synchronous active-low reset
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= PTR_ZERO;
            rd_ptr_q <= PTR_ZERO;
            count_q  <= CNT_ZERO;
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage write: only outside reset, only on an accepted write
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

`ifdef FORMAL
    // Design-intent properties (not yet proven; no .sby submitted with this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // wr_ptr is count slots after rd_ptr, modulo DEPTH
    reg [31:0] f_wr_expect;
    always @(*) begin
        f_wr_expect = {{(32-AW){1'b0}}, rd_ptr_q} + {{(32-CW){1'b0}}, count_q};
        if (f_wr_expect >= DEPTH_U) f_wr_expect = f_wr_expect - DEPTH_U;
    end

    always @(*) begin
        if (f_past_valid) begin
            assert(count_q <= FULL_COUNT);
            assert(wr_ptr_q <= LAST);
            assert(rd_ptr_q <= LAST);
            assert(full == (count_q == FULL_COUNT));
            assert(empty == (count_q == CNT_ZERO));
            assert(!(full && empty));
            assert(wr_ptr_q == f_wr_expect[AW-1:0]);
        end
    end

    (* anyconst *) reg [AW-1:0] f_addr;
    always @(*) assume(f_addr <= LAST);

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(count_q == CNT_ZERO);
                assert(wr_ptr_q == PTR_ZERO);
                assert(rd_ptr_q == PTR_ZERO);
            end else begin
                if ($past(wr_acc) && !$past(rd_acc)) begin
                    assert(count_q == $past(count_q) + CNT_ONE);
                end else if (!$past(wr_acc) && $past(rd_acc)) begin
                    assert(count_q == $past(count_q) - CNT_ONE);
                end else begin
                    assert(count_q == $past(count_q));
                end
                if ($past(wr_en) && $past(full)) begin
                    assert(wr_ptr_q == $past(wr_ptr_q));
                    assert(mem[f_addr] == $past(mem[f_addr]));
                end
                if ($past(rd_en) && $past(empty)) begin
                    assert(rd_ptr_q == $past(rd_ptr_q));
                end
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(full);
            cover(wr_en && full);
            cover(rd_en && empty);
            cover(wr_ptr_q == PTR_ZERO && $past(wr_ptr_q) == LAST && $past(rst_n));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
