`timescale 1ns / 1ps
`default_nettype none

// Self-checking testbench for sync_fifo.
// Two instances share one stimulus: A = DEPTH 8 x WIDTH 8, B = DEPTH 5 x WIDTH 12.
// Each has a reference queue; count, full, empty and rd_data (while non-empty)
// are checked after every rising edge. Coverage goals fail the run if missed.
module sync_fifo_tb;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg        rst_n;
    reg        wr_en;
    reg        rd_en;
    reg [11:0] wdata;

    // Instance A: DEPTH 8, WIDTH 8 (count is 4 bits)
    wire       a_full;
    wire       a_empty;
    wire [7:0] a_rdata;
    wire [3:0] a_count;

    // Instance B: DEPTH 5, WIDTH 12 (count is 3 bits)
    wire        b_full;
    wire        b_empty;
    wire [11:0] b_rdata;
    wire [2:0]  b_count;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) u_a (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wdata[7:0]),
        .full    (a_full),
        .rd_en   (rd_en),
        .rd_data (a_rdata),
        .empty   (a_empty),
        .count   (a_count)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) u_b (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wdata),
        .full    (b_full),
        .rd_en   (rd_en),
        .rd_data (b_rdata),
        .empty   (b_empty),
        .count   (b_count)
    );

    // Reference queue A
    reg [7:0]  a_q [0:7];
    reg [2:0]  a_head;
    reg [2:0]  a_tail;
    reg [3:0]  a_cnt;
    // Reference queue B
    reg [11:0] b_q [0:4];
    reg [2:0]  b_head;
    reg [2:0]  b_tail;
    reg [2:0]  b_cnt;

    reg acc_w;
    reg acc_r;

    integer passed;
    integer failed;

    // Coverage counters
    integer a_cov_full, a_cov_wr_full, a_cov_rd_empty, a_cov_both_empty;
    integer a_cov_both_full, a_cov_both_mid, a_cov_drain, a_cov_wrap, a_cov_rst_traffic;
    integer b_cov_full, b_cov_wr_full, b_cov_rd_empty, b_cov_both_empty;
    integer b_cov_both_full, b_cov_both_mid, b_cov_drain, b_cov_wrap, b_cov_rst_traffic;
    reg     a_seen_full;
    reg     b_seen_full;
    integer a_rd_since_rst;
    integer b_rd_since_rst;

    reg [31:0] rng;
    integer    i;
    reg [8*64-1:0] nonce;

    task next_rng;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    // Reference model update, using the inputs sampled at this rising edge
    task model_update;
        begin
            if (!rst_n) begin
                if ((a_cnt != 4'd0) && (wr_en || rd_en)) a_cov_rst_traffic = a_cov_rst_traffic + 1;
                if ((b_cnt != 3'd0) && (wr_en || rd_en)) b_cov_rst_traffic = b_cov_rst_traffic + 1;
                a_cnt = 4'd0; a_head = 3'd0; a_tail = 3'd0;
                b_cnt = 3'd0; b_head = 3'd0; b_tail = 3'd0;
                a_rd_since_rst = 0; b_rd_since_rst = 0;
                a_seen_full = 1'b0; b_seen_full = 1'b0;
            end else begin
                // ---------- A ----------
                if (wr_en && (a_cnt == 4'd8)) a_cov_wr_full = a_cov_wr_full + 1;
                if (rd_en && (a_cnt == 4'd0)) a_cov_rd_empty = a_cov_rd_empty + 1;
                if (wr_en && rd_en) begin
                    if (a_cnt == 4'd0)      a_cov_both_empty = a_cov_both_empty + 1;
                    else if (a_cnt == 4'd8) a_cov_both_full  = a_cov_both_full + 1;
                    else                    a_cov_both_mid   = a_cov_both_mid + 1;
                end
                acc_w = wr_en && (a_cnt != 4'd8);
                acc_r = rd_en && (a_cnt != 4'd0);
                if (acc_w) begin
                    a_q[a_tail] = wdata[7:0];
                    a_tail = (a_tail == 3'd7) ? 3'd0 : a_tail + 3'd1;
                end
                if (acc_r) begin
                    a_head = (a_head == 3'd7) ? 3'd0 : a_head + 3'd1;
                    a_rd_since_rst = a_rd_since_rst + 1;
                    if (a_rd_since_rst == 9) a_cov_wrap = a_cov_wrap + 1;
                end
                if (acc_w && !acc_r)      a_cnt = a_cnt + 4'd1;
                else if (acc_r && !acc_w) a_cnt = a_cnt - 4'd1;
                if (a_cnt == 4'd8) begin
                    a_cov_full = a_cov_full + 1;
                    a_seen_full = 1'b1;
                end
                if ((a_cnt == 4'd0) && a_seen_full) begin
                    a_cov_drain = a_cov_drain + 1;
                    a_seen_full = 1'b0;
                end

                // ---------- B ----------
                if (wr_en && (b_cnt == 3'd5)) b_cov_wr_full = b_cov_wr_full + 1;
                if (rd_en && (b_cnt == 3'd0)) b_cov_rd_empty = b_cov_rd_empty + 1;
                if (wr_en && rd_en) begin
                    if (b_cnt == 3'd0)      b_cov_both_empty = b_cov_both_empty + 1;
                    else if (b_cnt == 3'd5) b_cov_both_full  = b_cov_both_full + 1;
                    else                    b_cov_both_mid   = b_cov_both_mid + 1;
                end
                acc_w = wr_en && (b_cnt != 3'd5);
                acc_r = rd_en && (b_cnt != 3'd0);
                if (acc_w) begin
                    b_q[b_tail] = wdata;
                    b_tail = (b_tail == 3'd4) ? 3'd0 : b_tail + 3'd1;
                end
                if (acc_r) begin
                    b_head = (b_head == 3'd4) ? 3'd0 : b_head + 3'd1;
                    b_rd_since_rst = b_rd_since_rst + 1;
                    if (b_rd_since_rst == 6) b_cov_wrap = b_cov_wrap + 1;
                end
                if (acc_w && !acc_r)      b_cnt = b_cnt + 3'd1;
                else if (acc_r && !acc_w) b_cnt = b_cnt - 3'd1;
                if (b_cnt == 3'd5) begin
                    b_cov_full = b_cov_full + 1;
                    b_seen_full = 1'b1;
                end
                if ((b_cnt == 3'd0) && b_seen_full) begin
                    b_cov_drain = b_cov_drain + 1;
                    b_seen_full = 1'b0;
                end
            end
        end
    endtask

    // Compare every defined output against the reference model
    task check_outputs;
        begin
            // A
            if (a_count === a_cnt) passed = passed + 1;
            else begin failed = failed + 1; $error("%0t A: count=%0d expected %0d", $time, a_count, a_cnt); end
            if (a_full === (a_cnt == 4'd8)) passed = passed + 1;
            else begin failed = failed + 1; $error("%0t A: full=%b expected %b", $time, a_full, (a_cnt == 4'd8)); end
            if (a_empty === (a_cnt == 4'd0)) passed = passed + 1;
            else begin failed = failed + 1; $error("%0t A: empty=%b expected %b", $time, a_empty, (a_cnt == 4'd0)); end
            if (a_cnt != 4'd0) begin
                if (a_rdata === a_q[a_head]) passed = passed + 1;
                else begin failed = failed + 1; $error("%0t A: rd_data=%h expected %h", $time, a_rdata, a_q[a_head]); end
            end
            // B
            if (b_count === b_cnt) passed = passed + 1;
            else begin failed = failed + 1; $error("%0t B: count=%0d expected %0d", $time, b_count, b_cnt); end
            if (b_full === (b_cnt == 3'd5)) passed = passed + 1;
            else begin failed = failed + 1; $error("%0t B: full=%b expected %b", $time, b_full, (b_cnt == 3'd5)); end
            if (b_empty === (b_cnt == 3'd0)) passed = passed + 1;
            else begin failed = failed + 1; $error("%0t B: empty=%b expected %b", $time, b_empty, (b_cnt == 3'd0)); end
            if (b_cnt != 3'd0) begin
                if (b_rdata === b_q[b_head]) passed = passed + 1;
                else begin failed = failed + 1; $error("%0t B: rd_data=%h expected %h", $time, b_rdata, b_q[b_head]); end
            end
        end
    endtask

    // One clock cycle: drive at the falling edge, model at the rising edge, check after it
    task step;
        input        w;
        input        r;
        input        rn;
        input [11:0] d;
        begin
            @(negedge clk);
            wr_en = w;
            rd_en = r;
            rst_n = rn;
            wdata = d;
            @(posedge clk);
            model_update;
            #1;
            check_outputs;
        end
    endtask

    task rand_step;
        input [7:0] wr_th;
        input [7:0] rd_th;
        input       rn;
        begin
            next_rng;
            step((rng[7:0] < wr_th), (rng[15:8] < rd_th), rn, rng[27:16]);
        end
    endtask

    task cover_goal;
        input integer      hits;
        input [8*32-1:0]   name;
        begin
            if (hits > 0) passed = passed + 1;
            else begin failed = failed + 1; $error("coverage goal not reached: %0s", name); end
        end
    endtask

    initial begin
        passed = 0; failed = 0;
        a_cov_full = 0; a_cov_wr_full = 0; a_cov_rd_empty = 0; a_cov_both_empty = 0;
        a_cov_both_full = 0; a_cov_both_mid = 0; a_cov_drain = 0; a_cov_wrap = 0; a_cov_rst_traffic = 0;
        b_cov_full = 0; b_cov_wr_full = 0; b_cov_rd_empty = 0; b_cov_both_empty = 0;
        b_cov_both_full = 0; b_cov_both_mid = 0; b_cov_drain = 0; b_cov_wrap = 0; b_cov_rst_traffic = 0;
        a_seen_full = 1'b0; b_seen_full = 1'b0;
        a_rd_since_rst = 0; b_rd_since_rst = 0;
        a_cnt = 4'd0; a_head = 3'd0; a_tail = 3'd0;
        b_cnt = 3'd0; b_head = 3'd0; b_tail = 3'd0;
        acc_w = 1'b0; acc_r = 1'b0;
        rst_n = 1'b0; wr_en = 1'b0; rd_en = 1'b0; wdata = 12'd0;
        rng = 32'h1234_5678;
        nonce = {64{8'h00}};

        // 1. Reset with requests active: requests during reset are ignored
        step(1'b1, 1'b1, 1'b0, 12'h0AA);
        step(1'b1, 1'b1, 1'b0, 12'h0AB);
        step(1'b1, 1'b1, 1'b0, 12'h0AC);

        // 2. Read while empty
        step(1'b0, 1'b1, 1'b1, 12'h000);
        step(1'b0, 1'b1, 1'b1, 12'h000);

        // 3. Write and read together when empty: only the write is accepted
        step(1'b1, 1'b1, 1'b1, 12'h101);

        // 4. Write and read together in between
        step(1'b1, 1'b1, 1'b1, 12'h102);

        // 5. Fill past full on both: writes while full are dropped
        for (i = 0; i < 12; i = i + 1) begin
            step(1'b1, 1'b0, 1'b1, 12'h200 + i[11:0]);
        end

        // 6. Write and read together when full: only the read is accepted
        step(1'b1, 1'b1, 1'b1, 12'h300);
        step(1'b1, 1'b1, 1'b1, 12'h301);

        // 7. Drain past empty on both
        for (i = 0; i < 12; i = i + 1) begin
            step(1'b0, 1'b1, 1'b1, 12'h000);
        end

        // 8. Random traffic: balanced, write-heavy, read-heavy
        for (i = 0; i < 200; i = i + 1) rand_step(8'd128, 8'd128, 1'b1);
        for (i = 0; i < 200; i = i + 1) rand_step(8'd200, 8'd80,  1'b1);
        for (i = 0; i < 200; i = i + 1) rand_step(8'd80,  8'd200, 1'b1);

        // 9. Reset during traffic (both FIFOs hold entries before reset)
        step(1'b1, 1'b0, 1'b1, 12'h401);
        step(1'b1, 1'b0, 1'b1, 12'h402);
        step(1'b1, 1'b0, 1'b1, 12'h403);
        step(1'b1, 1'b1, 1'b0, 12'h404);
        step(1'b1, 1'b1, 1'b0, 12'h405);
        for (i = 0; i < 100; i = i + 1) rand_step(8'd128, 8'd128, 1'b1);

        // 10. Write-heavy, then reset with random requests, then balanced
        for (i = 0; i < 30; i = i + 1) rand_step(8'd220, 8'd60, 1'b1);
        rand_step(8'd128, 8'd128, 1'b0);
        for (i = 0; i < 200; i = i + 1) rand_step(8'd128, 8'd128, 1'b1);

        // 11. Drain to idle
        for (i = 0; i < 10; i = i + 1) step(1'b0, 1'b1, 1'b1, 12'h000);

        // Coverage goals
        cover_goal(a_cov_full,        "A full");
        cover_goal(a_cov_wr_full,     "A write while full");
        cover_goal(a_cov_drain,       "A drain to empty after full");
        cover_goal(a_cov_rd_empty,    "A read while empty");
        cover_goal(a_cov_both_empty,  "A write+read when empty");
        cover_goal(a_cov_both_full,   "A write+read when full");
        cover_goal(a_cov_both_mid,    "A write+read in between");
        cover_goal(a_cov_wrap,        "A pointer wrap");
        cover_goal(a_cov_rst_traffic, "A reset during traffic");
        cover_goal(b_cov_full,        "B full");
        cover_goal(b_cov_wr_full,     "B write while full");
        cover_goal(b_cov_drain,       "B drain to empty after full");
        cover_goal(b_cov_rd_empty,    "B read while empty");
        cover_goal(b_cov_both_empty,  "B write+read when empty");
        cover_goal(b_cov_both_full,   "B write+read when full");
        cover_goal(b_cov_both_mid,    "B write+read in between");
        cover_goal(b_cov_wrap,        "B pointer wrap");
        cover_goal(b_cov_rst_traffic, "B reset during traffic");

        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {64{8'h00}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

